css:
:root {
  --numeric-border: #223151;
  --numeric-background: #D7D8DB;
  --numeric-text: #000000;
  --numeric-unit: #0A638F;
  --numeric-font-size: 18px;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.numeric-widget,
.numeric-widget * {
  box-sizing: border-box;
}

.numeric-widget {
  width: 100%;
  height: 100%;
  padding: 2px;
  overflow: hidden;
  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.numeric-frame {
  display: flex;
  flex-direction: column;
  gap: 2px;

  width: 100%;
  height: 100%;
  padding: 4px 6px;
  overflow: hidden;

  border: 1px solid var(--numeric-border);
  border-radius: 4px;
  background: var(--numeric-background);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    inset 0 -1px 0 rgba(85, 93, 105, 0.12);
}

.numeric-screen {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  justify-content: center;

  width: 100%;
  min-width: 0;
  min-height: 0;
  padding: 0 4px;
  overflow: hidden;

  border: 1px solid #87919E;
  border-radius: 2px;
  background: var(--numeric-background);

  box-shadow:
    inset 0 1px 2px rgba(34, 49, 81, 0.12),
    inset 0 -1px 0 rgba(255, 255, 255, 0.45);
}

.numeric-unit-row {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;

  width: 100%;
  min-width: 0;
  overflow: hidden;
}

.numeric-value,
.numeric-unit {
  display: block;
  flex: 0 0 auto;

  font-family:
    "IBM Plex Mono",
    Consolas,
    "Liberation Mono",
    monospace;

  font-size: var(--numeric-font-size);
  font-weight: 550;
  font-style: normal;
  font-variant-numeric: tabular-nums;
  font-variant-ligatures: none;

  line-height: 1.2;
  letter-spacing: 0;
  white-space: nowrap;
}

.numeric-value {
  color: var(--numeric-text);
  text-align: center;
}

.numeric-unit {
  color: var(--numeric-unit);
  text-align: left;
}

.numeric-frame {
  padding: 2px 6px;
}

