"use strict";

(function () {
  const MAX_FONT_SIZE = 24;

  let frameElement = null;
  let screenElement = null;
  let valueElement = null;
  let unitElement = null;
  let unitRowElement = null;

  let lastUpdate = null;
  let resizeObserver = null;
  let layoutFrame = null;

  function pixels(value) {
    return parseFloat(value) || 0;
  }

  function fitValue() {
    if (
      !frameElement ||
      !screenElement ||
      !valueElement ||
      !unitElement ||
      !unitRowElement
    ) {
      return;
    }

    const frameStyles = getComputedStyle(frameElement);
    const screenStyles = getComputedStyle(screenElement);

    const innerHeight =
      frameElement.clientHeight -
      pixels(frameStyles.paddingTop) -
      pixels(frameStyles.paddingBottom);

    const gap = pixels(frameStyles.rowGap);

    const screenBorders =
      pixels(screenStyles.borderTopWidth) +
      pixels(screenStyles.borderBottomWidth);

    const availableWidth =
      screenElement.clientWidth -
      pixels(screenStyles.paddingLeft) -
      pixels(screenStyles.paddingRight);

    const unitWidth = unitRowElement.clientWidth;

    if (
      innerHeight <= gap + screenBorders ||
      availableWidth <= 0 ||
      unitWidth <= 0
    ) {
      return;
    }

    /*
     * Reserva altura para el número y la unidad.
     * Ambos mantienen el mismo tamaño de letra.
     */
    const baseSize = Math.min(
      MAX_FONT_SIZE,
      (innerHeight - gap - screenBorders) / 2.4
    );

    frameElement.style.setProperty(
      "--numeric-font-size",
      baseSize + "px"
    );

    /*
     * Las medidas no dependen del zoom del editor.
     * Reduce ambos textos si alguno supera el ancho disponible.
     */
    const valueWidth = valueElement.scrollWidth;
    const measuredUnitWidth = unitElement.scrollWidth;

    const valueScale =
      Math.max(1, availableWidth - 2) /
      Math.max(1, valueWidth);

    const unitScale =
      Math.max(1, unitWidth - 2) /
      Math.max(1, measuredUnitWidth);

    const scale = Math.min(1, valueScale, unitScale);

    frameElement.style.setProperty(
      "--numeric-font-size",
      (baseSize * scale) + "px"
    );
  }

  function scheduleFit() {
    if (layoutFrame !== null) return;

    layoutFrame = requestAnimationFrame(function () {
      layoutFrame = null;
      fitValue();
    });
  }

  function render(w) {
    if (!valueElement) return;

    const raw = w ? w.value : null;
    let numericValue = NaN;

    if (typeof raw === "number") {
      numericValue = raw;
    } else if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      numericValue = Number(raw);
    }

    const valid = Number.isFinite(numericValue);
    const text = valid ? String(numericValue) : "—";

    // Conserva el valor recibido sin redondeo adicional.
    valueElement.textContent = text;

    valueElement.setAttribute(
      "aria-label",
      valid
        ? "Velocidad: " + text + " revoluciones por minuto"
        : "Sin valor numérico"
    );

    scheduleFit();
  }

  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    frameElement = document.querySelector(".numeric-frame");
    screenElement = document.querySelector(".numeric-screen");
    valueElement = document.querySelector(".numeric-value");
    unitElement = document.querySelector(".numeric-unit");
    unitRowElement = document.querySelector(".numeric-unit-row");

    if (
      !frameElement ||
      !screenElement ||
      !valueElement ||
      !unitElement ||
      !unitRowElement
    ) {
      return;
    }

    render(lastUpdate || window.WIDGET || null);
    fitValue();

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(scheduleFit);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(scheduleFit);
      resizeObserver.observe(frameElement);
    } else {
      window.addEventListener("resize", scheduleFit);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
